<script setup lang="ts">
type P={id:string;status:string;model?:{name:string}|null;modelVersion?:{version:string}|null;metadata:any};type A={id:string;title:string;status:string;analysisContents:any[];predictions:P[]};const config=useRuntimeConfig();const api=String(config.public.apiBase||"");const analyses=ref<A[]>([]);const loading=ref(true);const error=ref("");async function load(){loading.value=true;try{const r=await $fetch<{analyses:A[];message?:string}>(`${api}/api/intelligence/graph`,{credentials:"include"});analyses.value=r.analyses||[]}catch(e:any){error.value=e?.data?.message||"Unable to load pipeline state."}finally{loading.value=false}}await load();const evidence=computed(()=>analyses.value.flatMap(a=>a.analysisContents));const predictions=computed(()=>analyses.value.flatMap(a=>a.predictions));const modelDetails=computed(()=>[...new Set(predictions.value.filter(p=>p.model?.name).map(p=>`${p.model?.name}${p.modelVersion?.version?` v${p.modelVersion.version}`:""}`))].join(", "));const completed=computed(()=>predictions.value.filter(p=>p.status==="COMPLETED").length);const failed=computed(()=>predictions.value.filter(p=>p.status==="FAILED").length);const active=computed(()=>predictions.value.some(p=>p.status==="PROCESSING")||analyses.value.some(a=>a.status==="PROCESSING"));const stages=computed(()=>[{name:"Evidence ingestion",count:evidence.value.length,status:evidence.value.length?"Recorded":"Awaiting evidence"},{name:"Preprocessing",count:evidence.value.length,status:evidence.value.length?"Local deterministic intake":"Awaiting evidence"},{name:"Model selection",count:new Set(predictions.value.map(p=>p.model?.name).filter(Boolean)).size,status:modelDetails.value||"No model association on deterministic MVP predictions"},{name:"Prediction",count:predictions.value.length,status:active.value?"Processing":failed.value?`${failed.value} failed`:completed.value?`${completed.value} completed`:"Awaiting analysis"},{name:"Evidence aggregation",count:completed.value,status:completed.value?"Available in reports":"Awaiting completed predictions"},{name:"Explainability",count:completed.value,status:completed.value?"Signals and metadata recorded":"Awaiting predictions"},{name:"Verdict",count:0,status:"No authenticity verdict produced by deterministic MVP"}]);
</script>
<template><main class="mx-auto max-w-5xl space-y-6 p-5 sm:p-8"><div class="mb-4"><DashboardBackToDashboard /></div><DashboardNav/><header><p class="text-xs font-semibold uppercase tracking-widest text-[var(--vl-sage-dark)]">Intelligence</p><h1 class="mt-2 text-3xl font-semibold">AI pipeline</h1><p class="mt-2 text-sm text-[var(--vl-muted)]">Live counts from saved evidence and predictions. The current engine is deterministic MVP logic, not a trained ML model.</p></header><div v-if="loading" class="rounded-2xl bg-white/70 p-7">Loading pipeline…</div><div v-else-if="error" class="rounded-2xl border border-red-200 p-6">{{error}} <button class="underline" @click="load">Retry</button></div><template v-else><section class="grid gap-3 sm:grid-cols-4"><div class="rounded-2xl border bg-white/70 p-4"><small>Evidence</small><p class="mt-1 text-2xl font-semibold">{{evidence.length}}</p></div><div class="rounded-2xl border bg-white/70 p-4"><small>Predictions</small><p class="mt-1 text-2xl font-semibold">{{predictions.length}}</p></div><div class="rounded-2xl border bg-white/70 p-4"><small>Completed</small><p class="mt-1 text-2xl font-semibold">{{completed}}</p></div><div class="rounded-2xl border bg-white/70 p-4"><small>Failed</small><p class="mt-1 text-2xl font-semibold">{{failed}}</p></div></section><ol class="space-y-3"><li v-for="(s,i) in stages" :key="s.name" class="flex items-center gap-4 rounded-2xl border border-[var(--vl-border)] bg-white/70 p-5"><span class="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-[#e8ece2] text-sm font-semibold">{{i+1}}</span><div class="min-w-0 flex-1"><h2 class="font-semibold">{{s.name}}</h2><p class="mt-1 text-sm text-[var(--vl-muted)]">{{s.status}}</p></div><span class="text-lg font-semibold">{{s.count}}</span></li></ol><p class="text-xs text-[var(--vl-muted)]">Pipeline stages are descriptive indicators based on persisted records. No external model inference or unsupported authenticity claims are made.</p></template></main></template>




